from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/1656536/000095017023007849/dbtx-20221231.htm','Decibel issuer annual filing identifies DBOTO,AAV103/104,DBATO,DB020 and cell-selective gene-therapy discovery/regeneration platform. Historic status does not establish current continuation.')
b=ev('https://www.sec.gov/Archives/edgar/data/872589/000110465923095116/tm2324731d1_ex99-a1a.htm','2023 acquisition disclosure also identifies AAV105 undisclosed single-gene hearing-loss programme and supporting-cell-to-cochlear/vestibular hair-cell regeneration programmes. No invented mutation target for AAV105.')
c=ev('https://www.sec.gov/Archives/edgar/data/872589/000110465923103362/tm2324731d10_ex99-a5a.htm','Regeneron confirms Decibel acquisition completed September25 2023. Decibel original development relationship retained; other Regeneron products not attributed.')
d=ev('https://www.fda.gov/news-events/press-announcements/fda-approves-first-ever-gene-therapy-treatment-genetic-hearing-loss-under-national-priority-voucher','FDA confirms accelerated approval of Otarmeni/lunsotogeneparvec-cwha for specified OTOF-related hearing loss inApril2026. Approval scope is not all genetic deafness; ongoing confirmatory obligations apply.')
e=ev('https://www.otarmeni.com/','Current manufacturer product site says therapy available/administered at activated authorized treatment centres. Supports current product availability,not merely approval forecast.')
f=ev('https://regeneronpharmaceuticalsinc.gcs-web.com/news-releases/news-release-details/otarmenitm-lunsotogene-parvec-cwha-approved-fda-first-and-only','April2026 issuer explicitly confirms DBOTO renamed Otarmeni and free US provision. Product identity grouped acrossdevelopmentcode/brand/generic name.')
products=[p('Otarmeni','AAV gene therapy for eligible patients with OTOF-related hearing loss; US accelerated approval and authorized-centre availability confirmed.',d,'commercial',typ='product',aliases=['DB-OTO'],evidence=[a,c,d,e,f],attributes={'generic_name':'lunsotogene parvec-cwha','US_regulatory_status':'accelerated_approval','current_provider':'Regeneron','US_supply':'free_at_activated_authorized_treatment_centres'})]
products[0]['aliases']+=[{'alias':'lunsotogene parvec-cwha','alias_type':'generic_name'},{'alias':'lunsotogene parvec','alias_type':'generic_name'}]
for n,desc in [('AAV.103','Historical investigational GJB2-directed hearing-loss gene-therapy programme.'),('AAV.104','Historical investigational STRC/stereocilin hearing-loss gene-therapy programme.'),('AAV.105','Historical monogenic hearing-loss gene-therapy programme; specific target undisclosed.'),('DB-ATO','Historical ATOH1 gene-therapy programme for vestibular hair-cell regeneration/balance disorders.'),('DB-020','Investigational intratympanic cisplatin-ototoxicity prevention formulation; current later-stage continuation unverified.'),('Decibel cochlear hair-cell regeneration programme','Historical gene-therapy research programme converting supporting cells into cochlear hair cells; exact code unverified.')]:
 products.append(p(n,desc,a,'unknown',evidence=[a,b,c]))
products.append(p('Decibel cell-selective gene-therapy platform','Historical inner-ear gene-expression and cell-selective-promoter discovery technology.',a,'unknown',typ='technology',evidence=[a,c]))
co=company('Decibel Therapeutics Inc',products,[a,b,c,d,e,f],'Seven drug/research programme identities plus historical discovery technology entered. DBOTO/Otarmeni/generic identity grouped; US2026 accelerated approval and actual activated-centre offering verified. Decibel originaldeveloper relationship,not ownership of allRegeneronproducts. Current legacy programmecontinuation,exact DB020 formulation rights,additional historical codes andsubsequent licensing still require reconciliation.')
(out/'batch-0145.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
